import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { presentIndividualDetail } from '../../../interfaces/present.inidvidual.interface';
import { PresentService } from '../../../services/present/present.service';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { presentEvents } from '../../../interfaces/present.tool.interface';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { Subscription } from 'rxjs';
import { SecureStorageService } from '../../../../core/services/storage/secure-storage.service';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';

@Component({
  selector: 'present-popup',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [ButtonComponent, MatCheckboxModule, FormsModule],
  templateUrl: './present-popup.component.html',
  styleUrl: './present-popup.component.scss'
})
export class PresentPopupComponent {
  @Input() presentDetail: presentIndividualDetail;
  @Input() nPresentid: string;
  @Output() presentEvents = new EventEmitter<toolEvents>();
  @Input() isPaused: boolean;
  @Input() isEndPresentation: boolean;
  @Output() isEndPresentationChange = new EventEmitter<boolean>();

  presentSubscribe: Subscription;
  nUserid: string;
  isJoining: boolean = false;
  @Input() isPresentationEnded: boolean = false;
  showPausedDialog : boolean  = false;
  bShowAgain: boolean = false;
  
  @Input() nCaseid: string
  
  constructor(private presentSerice: PresentService, private cdr: ChangeDetectorRef, private socket: SocketService, private store: SecureStorageService, private tost: TostbarService, private router: Router) {
    this.presentSubscribe = this.socket.getPresentationTools().subscribe((res: presentEvents) => {
      const data = res?.data;


      if (this.isPaused) return;

      if (['PAUSED', 'LIVE'].includes(res.event)) {
        if (data.cStatus == 'L' && this.presentDetail.cStatus == 'P' && !this.presentDetail?.isHost) {
          this.presentEvents.emit({ event: 'REFRESH-PRESENTATION', data: {} });
        }
        this.presentDetail.cStatus = data.cStatus;
      } else if (res.event == 'END') {
        // End presentation here
        // this.presentEvents.emit({ event: 'PRESENTATION-END', data: {} });

        this.isPresentationEnded = true;
        this.cdr.detectChanges();
      } else if (res.event == 'USER-MANAGE') {
        if (data.nPresentid != this.nPresentid) return;

        if (data.cPermission == 'E') {
          this.presentDetail.cUStatus = data.cStatus;
          if (data.cStatus == 'A') {
            // this.socket.joinPresentation(this.nPresentid, this.nUserid, this.presentDetail?.isHost);
        
            this.presentEvents.emit({ event: 'USER-JOINED', data: {} });
          }
        } else if (data.cPermission == 'D') {
          this.presentDetail.cUStatus = null;
          this.presentEvents.emit({ event: 'USER-REMOVED', data: {} });
        }
      } else if (res.event == 'REQ-MANAGE') {
        if (data.nPresentid != this.nPresentid) return;
        this.presentDetail.cUAStatus = data.cStatus;


        if (this.presentDetail.cUStatus == 'I' && data.cStatus == 'A') {
          this.presentDetail.cUStatus = data.cStatus == 'A' ? 'A' : 'I';
          // this.socket.joinPresentation(this.nPresentid, this.nUserid, this.presentDetail?.isHost);
          this.joinPresentation('Y');
          return;

        }

        this.presentDetail.cUStatus = data.cStatus == 'A' ? 'A' : 'I';
        if (data.cStatus == 'A') {
          // this.socket.joinPresentation(this.nPresentid, this.nUserid, this.presentDetail?.isHost);
          if (!data.isHaveHighlight) {
            this.presentDetail.cUAStatus = 'J';
            this.presentEvents.emit({ event: 'USER-JOINED', data: {} });
          }
          // this.presentEvents.emit({ event: 'USER-JOINED', data: {} });
        }
      }
      this.cdr.detectChanges();
    });



  }



  async ngOnInit() {
    this.nUserid = await this.store.getUserId();
    this.bShowAgain =  JSON.parse(this.store.getStorage('bShowAgain')) || false;
    this.cdr.detectChanges();
  }

  RequestToReJoin() {
    this.presentDetail.cUAStatus = 'RQ';
    this.presentSerice.requestToJoin(this.nPresentid);
    this.cdr.detectChanges();
  }


  ngOnDestroy(): void {
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
    try {
      if (this.presentSubscribe) {
        this.presentSubscribe.unsubscribe();
      }

      this.socket.leavePresentation(this.nPresentid, this.nUserid)
    } catch (error) {

    }
  }


  async endPresentation() {
    await this.presentSerice.endPresentation(this.nPresentid);

    this.presentEvents.emit({ event: 'PRESENTATION-END', data: {} });
  }


  async joinPresentation(flag: 'Y' | 'N') {
    this.isJoining = true;
    this.cdr.detectChanges();
    if (flag == 'N') {
      await this.presentSerice.unsaveHighlights(this.nPresentid);
    }
    const res = await this.presentSerice.userJoined(this.nPresentid)
    if (res.msg == 1) {
      this.presentDetail.cUAStatus = 'J';
      this.presentEvents.emit({ event: 'USER-JOINED', data: {} });
    } else {
      this.tost.error(res.msg);
    }

    this.isJoining = false;
    this.cdr.detectChanges();
  }


  async onEnd(isSave: boolean) {
    if (isSave) {
      this.tost.success('Presentation notes saved successfully');
      this.presentEvents.emit({ event: 'PRESENTATION-END', data: {} });
    } else {
      await this.presentSerice.unsaveHighlights(this.nPresentid);
      this.presentEvents.emit({ event: 'PRESENTATION-END', data: {} });
    }
  }

  close() {
    this.isEndPresentation = false;
    this.isEndPresentationChange.emit(this.isEndPresentation)
    this.cdr.detectChanges();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if(changes['isPaused']  && !this.bShowAgain){
      this.showPausedDialog  = changes['isPaused']?.currentValue;
    }
  }

  closePausedDialog(){
    this.showPausedDialog = false;
    this.store.setStorage('bShowAgain', this.bShowAgain);
    
  }

  gotoHome(){
    this.router.navigate(['/present/home', JSON.stringify({ id: this.nCaseid })]);
  }
}